SELECT s.soc, s.soctype, s.fundingtype, COUNT(*) AS total_records, SUM(CASE WHEN sa.avgscrread IS NULL THEN 1 ELSE 0 END) AS null_read, SUM(CASE WHEN sa.avgscrmath IS NULL THEN 1 ELSE 0 END) AS null_math, SUM(CASE WHEN sa.avgscrwrite IS NULL THEN 1 ELSE 0 END) AS null_write FROM satscores sa JOIN schools s ON sa.cds = s.cdscode GROUP BY s.soc, s.soctype, s.fundingtype ORDER BY total_records DESC;
